                />
              </th>
              {/* Draggable column headers */}
              {orderedColumns.map((col) => (
                <th
                  key={col.id}
                  draggable
                  onDragStart={(e) => onDragStart(e, col.id)}
                  onDragEnd={() => setDragSrcId(null)}
                  onDragOver={onDragOver}
                  onDrop={(e) => onDrop(e, col.id)}
                  title=\"Перетащите, чтобы изменить порядок\"
