export function OrdersTable({ orders }: { orders: Order[] }) {
  // ── selected row ids ──
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  // ── column order (drag & drop) ──
  const [columnOrder, setColumnOrder] = useState<string[]>(
    ALL_COLUMNS.map((c) => c.id),
  );
  const [dragSrcId, setDragSrcId] = useState<string | null>(null);

  const onDragStart = useCallback((e: React.DragEvent, colId: string) => {
    setDragSrcId(colId);
    e.dataTransfer.effectAllowed = 'move';
    (e.currentTarget as HTMLElement).style.opacity = '0.4';
  }, []);

  const onDragEnd = useCallback((e: React.DragEvent) => {
    setDragSrcId(null);
    (e.currentTarget as HTMLElement).style.opacity = '1';
  }, []);

  const onDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  }, []);

  const onDrop = useCallback(
    (e: React.DragEvent, targetId: string) => {
      e.preventDefault();
      if ("'!dragSrcId || dragSrcId === targetId) return;
      setColumnOrder((prev) => {
        const next = [...prev];
        const srcIdx = next.indexOf(dragSrcId);
        const tgtIdx = next.indexOf(targetId);
        next.splice(srcIdx, 1);
        next.splice(tgtIdx, 0, dragSrcId);
        return next;
      });
      setDragSrcId(null);
    },
    [dragSrcId],
  );

  // ── grouping by status ──
  const groupedData = useMemo(() => {
    const result: Array<Order | { __group: true; status: OrderStatus }> = [];
    for (const st of statusOrder) {
      const items = orders.filter((o) => o.status === st);
      if (items.length > 0) {
        result.push({ __group: true, status: st } as any);
        for (const item of items) result.push(item);
      }
    }
    return result;
  }, [orders]);

  // ── columns in current order ──
  const columns = useMemo(() => {
    return columnOrder
      .map((id) => ALL_COLUMNS.find((c) => c.id === id))
      .filter(Boolean) as ColumnMeta[];
  }, [columnOrder]);

  // ── table columns (for Gravity UI Table) ──
  const tableColumns = useMemo(() => {
    return columns.map((col) => ({
      id: col.id,
      name: col.name,
      width: col.width,
      align: col.align,
      template: col.template,
    }));
  }, [columns]);

  // ── handler for selection ──
  const onSelectionChange = useCallback((ids: string[]) => {
    setSelectedIds(ids);
  }, []);

  // ── getRowId: skip group rows ──
  const getRowId = useCallback((item: any) => {
    if (item.__group) return `__group_${item.status}`;
    return item.id;
  }, []);

  // ── getRowDescriptor: disable group rows ──
  const getRowDescriptor = useCallback((item: any) => {
    if (item.__group) {
      return { disabled: true, interactive: false, id: `__group_${item.status}` };
    }
    return undefined;
  }, []);

  // ── custom row render: detect group rows ──
  const renderBody = useCallback(
    (rows: React.ReactNode[]) => {
      let idx = 0;
      return groupedData.map((item) => {
        if ((item as any).__group) {
