          }}
        >
          Выбрано строк: <strong>{selectedIds.length}</strong>
        </div>
      )}

      <TableWithSelection
        data={groupedData}
        columns={tableColumns}
        selectedIds={selectedIds}
        onSelectionChange={onSelectionChange}
        getRowId={getRowId}
        getRowDescriptor={getRowDescriptor}
        verticalAlign=\"middle\"
        edgePadding
        // ── custom header render with drag & drop ──
        renderHeader={(
          cols: Array<{ id: string; name?: string }>,
          renderCell: (col: any) => React.ReactNode,
        ) => {
          // order columns according to columnOrder
          const orderedCols = columnOrder
            .map((id) => cols.find((c: any) => c.id === id))
            .filter(Boolean);

          return (
            <tr>
              {/* selection checkbox column */}
              <th style={{ width: 40, padding: '0 12px' }} />
              {orderedCols.map((col: any, idx: number) => {
                const isLast = idx === orderedCols.length - 1;
                return (
                  <th
                    key={col.id}
                    draggable
                    onDragStart={(e) => onDragStart(e, col.id)}
