                      onClick={() => toggleRow(item.id)}
                      style={{
                        cursor: 'pointer',
                        background: isSelected
                          ? 'var(--g-color-base-selection)'
                          : 'transparent',
                        transition: 'background 0.1s',
                      }}
                      onMouseEnter={(e) => {
                        if ("'!isSelected) {
