                              style={{
                                display: 'inline-block',
                                padding: '2px 10px',
                                borderRadius: 10,
                                fontSize: 12,
                                fontWeight: 600,
                                background: STATUS_COLORS[item.status],
                                color: 'var(--g-color-text-primary)',
                              }}
                            >
                              {item.status}
                            </span>
                          ) : (
                            formatCell(col, item)
                          )}
                        </td>
                      ))}
                    </tr>
                  );
                })}
              </>
            ))}
          </tbody>
        </table>

        {/* Empty state */}
        {orders.length === 0 && (
          <div
            style={{
              textAlign: 'center',
              padding: 40,
              color: 'var(--g-color-text-hint)',
            }}
          >
            Нет данных
          </div>
        )}
      </div>
    </div>
  );
}
ENDOFFILE
echo \"OrdersTable.tsx updated\""
